const COVERS: Record<string, () => ReactNode> = {
  fieldnotes: Fieldnotes,
  tidewater: Tidewater,
  kiln: Kiln,
  "lumen-type": Lumen,
  northbound: Northbound,
  "small-rooms": SmallRooms,
